  FT["BN-S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-261129"] = {"id":"BN-S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-261129","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":3,"structureMode":"SECTION","title":{"zh":"宪法职能转移与相应条款命令 1989","en":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS ORDER 1989","orig":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS ORDER 1989","vi":"Sắc lệnh chuyển giao chức năng và các quy định kèm theo của Hiến pháp năm 1989","th":"คำสั่งการโอนหน้าที่และบทบัญญัติที่เกี่ยวข้องตามรัฐธรรมนูญ พ.ศ. 2532","id":"Perintah Pengalihan Fungsi dan Ketentuan Konsekuensial menurut Konstitusi Tahun 1989","ms":"Perintah Pemindahan Fungsi dan Peruntukan Bersampingan di bawah Perlembagaan 1989"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONSEQUENTIAL-PROVISIONS-ORDER-1989.pdf》（1 页），本次切分 3 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONSEQUENTIAL-PROVISIONS-ORDER-1989.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-261129-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Constitution (Transfer of Functions Citation. and Consequential Provisions! Order, 1989."}},{"id":"BN-S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-261129-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In this Order \"functions\" includes any powers, duties, privileges Interpretation. or benefits conferred or imposed by any written law on any person or authority."}},{"id":"BN-S-51-1989-CONSTITUTION-TRANSFER-OF-FUNCTIONS-AND-CONS-261129-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The functions conferred or imposed on the person or authority Transfer of specified in the first column of the Schedule by the provisions of the Functions. law specified opposite thereto in the second column of that Schedule are hereby transferred to the person or authority specified opposite thereto in the third column of that Schedule.\n\nSCHEDULE\n\nCRIMINAL PROCEDURE CODE (CHAPTER 7) First Column Second Column Third Column His Majesty The section 262(3) and The Minister with Sultan and Yang (51 the approval of His Di-Pertuan in Majesty The Sultan Council and Yang Di-Pertuan Made this 5th day of October, 1989 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nHIS MAJESTY\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nOF BRUNEI DARUSSALAM"}}],"pack":"bn-p30","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CONSTITUTION TRANSFER OF FUNCTIONS AND CONSEQUENTIAL PROVISIONS ORDER 1989","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006"] = {"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":20,"structureMode":"SECTION","title":{"zh":"海关过境规则 2006","en":"CUSTOMS CUSTOMS TRANSIT RULES 2006","orig":"CUSTOMS CUSTOMS TRANSIT RULES 2006","vi":"Quy tắc Quá cảnh hải quan năm 2006","th":"ข้อกำหนดการขนถ่ายสินค้าผ่านแดนทางศุลกากร พ.ศ. 2549","id":"Peraturan Transit Kepabeanan Tahun 2006","ms":"Kaedah Transit Kastam 2006"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006.pdf》（10 页），本次切分 20 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Rules may be cited as the Customs (Customs Transit) Rules, 2006."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"These Rules shall apply to goods subjected to customs transit by the authority of the Royal Customs and Excise Department within Brunei"}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In these Rules, unless the context otherwise requires - \"authorised consignee\" means a person authorised by a proper officer of customs to receive goods directly at his premises without having to present them at the office of destination; \"authorised consignor\" means a person authorised by a proper officer of customs to send goods directly from his premises without having to present them at the office of departure; \"customs transit\" means the customs procedure under which goods in transit under customs control form one customs office to another Brunei Darussalam; \"dangerous goods\" means those substances and articles which may affect the interest of health, safety and national security; \"office of departure\" means any customs office where a customs transit operation commences; \"office of destination\" means any customs office where a customs transit operation terminates; \"sealable transport unit\" means a transport unit that is constructed and equipped such that - (a} customs seal can be easily and effectively affixed to it; (b} no goods can be removed from or introduced into the transport unit without leaving visible traces of tampering or without breaking the customs seal; (c} it contains no concealed space where goods may be hidden; and (d} all spaces capable of holding goods are readily accessible for customs inspection; \"transport unit\" includes (a} containers having an internal volume of one cubic metre or more, including demountable bodies of such containers; (b} road vehicles, including trailers and semi-trailers; (cJ railway coaches or wagons; (d} lighters, barges and other vessels; and ( e J air crafts.\n\nAND PROCEDURE of goods under customs transit."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"PART II"},"text":{"en":"(1) The Controller shall allow goods, other than prohibited and dangerous goods, to be transported under customs transit in Brunei Darussalam - (a} from an office of departure to an office of destination; (b} from an office of departure to an inland clearance depot; (c} from an inland clearance depot to an office of destination; (d} from one inland clearance depot to another inland clearance depot. (2} In relation to prohibited and dangerous goods and any other goods subject to specific control under any written law, sub-rule (ll shall only apply a permit has been issued thereto by the relevant competent authority. of duty."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"PART II"},"text":{"en":"Goods transported under customs transit shall not be subjected to the payment of customs duties, taxes and other charges, except those charges levied for specific services rendered in relation to such activity. to act as agents of authorised consignor or authorised consignee and other related"}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART II"},"heading":{"en":"Permission to act as agents of authorised consigner or authorised consignee"},"text":{"en":"(1) No person shall act as an agent for transacting any business relating to customs transit operations, except with the permission of a senior officer of\n\n(2) Where a person applies to a senior officer of customs for permission to an agent on behalf of the authorised consignor or authorised consignee, the applicant may be required to produce a written authority from such consignor or on whose behalf he is to act and failure to produce such authority may result in a refusal to grant the permission applied for.\n\n(3) Permission granted under sub-rule (1) may require the agent to provide such security as considered adequate by a senior officer of customs for ensuring and lawful conduct of the agent and his employees in matters related to the provisions of these Rules and any other written law.\n\n(4) Permission granted under sub-rule ( 1) may be suspended or cancelled by a senior officer of customs if the authorised consignor or authorised consignee, or their respective agent or the agent's employee - (a} commits a breach of any of the provisions of these Rules or any written law; or (b} fails to comply with any directions given by a proper officer of with regard to the customs transit operation made by such consignor or consignee, or their agent or the agent's employee.\n\n(5) Where a person is aggrieved by the decision of a senior officer of than the Controller, in respect of the following - (a} a refusal to grant permission under sub-rule (1);\n\n(b) the nature or amount of security requested for under sub-rule (3); or {c) the suspension or cancellation of the permission under sub-rule (4), month from the date of notification of the decision in writing to him, appeal to the Controller whose decision shall be final. persons authorised to act on behalf of employer."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"PART II"},"text":{"en":"(1) For the purposes of these Rules, a person, being the employee, may be allowed by a senior officer of customs to transact any business relating to customs transit operations generally at any office of departure or office of destination on behalf of his employer subject to the production and deposit of a signed authority to do so to the senior officer of customs.\n\n(2) The signed authority required under sub-rule (1) must identify specifically the employee concerned to the satisfaction of the senior officer of declaration and obligations of declarant."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"PART II"},"text":{"en":"(1) Where an authorised consignor or authorised consignee, or agent, is involved in transacting business in relation to a customs transit operation, such person shall submit a declaration in such form and manner as the Controller may determine in respect of the goods involved in the operation. (2l The declarant, together with any other persons having control over the goods, shall be responsible for the compliance with the obligations incurred under customs transit, in particular for ensuring that the goods are produced intact to the office of destination in accordance with the conditions imposed by the customs authority. to declare and interference."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"PART II"},"text":{"en":"i 1) Notwithstanding anything declared in rule 8, the customs authority shall take all necessary actions to enable the officer of customs on duty at the office of destination to identify the goods in transit and to detect any unauthorised\n\n(2) Where any unauthorised interference is detected, the person responsible for the interference and the person responsible for the commission of such interference shall be guilty of an offence and liable on conviction to a fine not exceeding $16,000, imprisonment for a term not exceeding 8 months or both. vehicles."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"PART II"},"text":{"en":"(1} With regard to a commercial vehicle, the proper officer of customs shall allow a transport unit that has a valid permit issued by the Director of Land Transport for the purpose of customs transit. \\2) For the purpose of sub-rule (1}. the driver of the transport unit shall have a valid driving license issued by a competent authority of the respective country. of seal."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"PART II"},"text":{"en":"Goods transported under customs transit shall, as far as possible, be conveyed in a sealable transport unit -\n\n(a) and where goods in customs transit are conveyed in a sealable transport unit, the customs authority may allow the original shipper seal to means of securing the sealable transport unit;\n\n(b) and where goods in customs transit are not conveyed in a sealable transport unit, the officer of customs at the office of departure shall affix relevant markings or seals on individual packages for the purpose of identification of the goods by the customs authority at the office of provision."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"PART II"},"text":{"en":"( 1) If it is considered that such measure is indispensable, the Controller\n\n(a) itinerary routes, where goods are required to be transported by following a prescribed itinerary;\n\n(b) whether customs escort is required during the transportation of and\n\n(c) time limits which are sufficient for the purposes of customs transit\n\n(2) In circumstances where escorts of the relevant authorities are required or considered necessary, the relevant authorities may impose prescribed charges for such services."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"PART II"},"text":{"en":"Where security is required to ensure that obligations ansmg from the customs transit operation will be fulfilled, the security shall be provided in such form and manner as the Controller may determine. Seal."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"PART II"},"text":{"en":"(1) A proper officer of customs may allow customs seals and identification affixed by the original shipper or foreign customs authority for the purposes of customs transit operations, unless they are found to be insufficient or insecure for the purpose of identification.\n\n(2) Subject to sub-rule (1), original shipper or foreign customs seals shall be deemed national seals and fastenings and shall be treated accordingly in respect of any legal provisions applicable to them. and breaking of seals."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"PART II"},"text":{"en":"Any person who removes or causes any breaking of seals or fastenings proper officer of customs is guilty of an offence and shall be liable on conviction to a fine not exceeding $16,000, imprisonment for a term not exceeding 8 months or both. outside office hours."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"PART II"},"text":{"en":"(1) At the request of the person concerned, and for reasons deemed valid by a senior officer of customs, the senior officer of customs may, insofar as administrative circumstances permit, perform the functions laid down for the purposes of customs transit outside normal office hours, provided that it is conducted within a customs control post and any decision made in respect of the request shall be recorded.\n\n(2) Any expenses incurred upon the request made under sub-rule (1) shall be borne by the person requesting such functions to be performed. EN-ROUTE. in office of destination."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"PART III"},"text":{"en":"A proper officer of customs shall allow a change in the office of destination without prior notification, except where such officer has specified that prior approval is necessary."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"PART III"},"text":{"en":"( 1) Where an accident or any other unforeseen event directly affecting a customs transit operation occurs involving any transport unit or goods, being part of the subject of a customs transit operation, the person concerned shall immediately make a report of a such accident or event to the nearest police station and take reasonable steps to inform customs authority of the same.\n\n(2) If the transport unit is rendered unserviceable due to an accident or any other unforeseen event, the customs authority shall allow the goods to be loaded onto another transport unit, subject to supervision by customs or other competent\n\n(3) The supervising authority in sub-rule (2) shall forthwith submit such report of the transfer of goods from one transport unit to another for the purpose of confirmation of such transfer to the Controller. of goods lost in transit."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"PART III"},"text":{"en":"(1) an accident or any other unforeseen event affecting the customs transit operation, the customs authority shall have the power to constitute a complete investigation to determine whether any of the goods in transit are lost during such customs transit operation.\n\n(2) The investigation shall be carried out in accordance with the powers of the customs authority under the Customs Order, 2006 or any regulations made and shall be subject to administrative notices with the Contracting\n\n(3) The power to investigate shall not derogate the obligation of the Contracting Parties under Article 28 Protocol 7 of the ASEAN Framework Agreement on the Facilitation of Goods in Transit.\n\nOF CUSTOMS TRANSIT OPERATION of customs transit operation."}},{"id":"BN-S-51-2006-CUSTOMS-CUSTOMS-TRANSIT-RULES-2006-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"PART IV"},"text":{"en":"(1) For the purpose of terminating a customs transit operation, the person concerned shall present the goods and the relevant declaration for such goods to a proper officer of customs at the office of destination within any time limit &xed, without the goods having undergone any change and without having been used, and with the customs seals or fastening marks intact. 12) When goods under customs transit are placed under another customs with the approval of the relevant customs authority, the proceeding customs transit operation will be deemed terminated thereon. Made this 8th. day of Safar, 1427 Hijriah corresponding to the 8th. day of\n\nDATO PADUKA HAJI ALI BIN APONG Permanent Secretary, Ministry of Finance, Brunei Darussalam. Dicetak oleh PENGIRAN HAJI ZAINAL ABIDIN BIN PENGIRAN SERI WIJAYA PENGIRAN HAJI AHMAD, Pemangku Pengarah Percetakan, di Jabatan Percetakan Kerajaan, Bandar Seri Begawan BB3510, Negara Brunei Darussalam."}}],"pack":"bn-p30","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"CUSTOMS CUSTOMS TRANSIT RULES 2006","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-51-2017-E-ELECTRICITY-ORDER-2017"] = {"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":69,"structureMode":"SECTION","title":{"zh":"电力命令 2017","en":"ELECTRICITY ORDER 2017","orig":"ELECTRICITY ORDER 2017","vi":"Sắc lệnh Điện lực năm 2017","th":"คำสั่งไฟฟ้า พ.ศ. 2560","id":"Perintah Ketenagalistrikan Tahun 2017","ms":"Perintah Elektrik 2017"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-51-2017-E-ELECTRICITY-ORDER-2017.pdf》（48 页），本次切分 69 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-51-2017-E-ELECTRICITY-ORDER-2017.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Citation, commencement and long title"},"text":{"en":"(1) This Order may be cited as the Electricity Order, 2017 and shall commence on a date to be appointed by the Minister, with the approval of His Majesty the Sultan and Yang Di-Pertuan, by notification published in the Gazette.\n\n(2) Different dates may be appointed under subsection (1) for different provisions of this Order or for different purposes of the same provision.\n\n(3) The long title of this Order is \"An Order to provide for the regulation and control of the generation, transmission, distribution and use of electricity, and to create criminal offences in connection therewith\"."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In this Order, unless the context otherwise requires - \"apparatus\" means any electrical apparatus, equipment or accessory and all apparatuses, machines, consuming devices and fittings in which one or more conductors are used or of which they form a part; \"authorised officer\" means any person appointed under section 411); \"cable detection work\" means any work of detecting or locating any electricity cable; \"code of practice\" means a code issued or approved by the Authority under means a person (a] to whom electricity is supplied and sold for consumption on that person's own premises; or\n\n(b) whose premises are for the time being connected to any system for the purpose of purchasing a supply of electricity for consumption on that person's own premises; \"distribute\" means to convey electricity by means of a distribution system -\n\n(a) from a main intake station to a distribution substation; or\n\n(b) from an electrical plant or a distribution substation to the electrical installation serving the premises of a consumer or, where such premises are not served by an electrical installation, from an electrical plant or a transmission substation directly to such premises; \"distribution system\" means a system of interconnected electric lines, electrical plants and substations used by a distribution licensee to distribute \"electric line\" means any line which is used for canying electricity for any purpose and includes -\n\n(a) any support for the line, that is to say, any structure, pole or other thing in, on, by or from which the line is or may be supported, carried or\n\n(b) any apparatus connected to the line for the purposes of canying\n\n(c) any wire, cable, tube, pipe or other similar thing (including its casing or coating) which surrounds or supports, or is surrounded or supported by, or is installed in close proximity to, or is supported, carried or in association with, the line; and\n\n(d) any electricity cable; \"electrical installation\" means any appliance, wire, fitting or other apparatus placed in, on, over or under any premises and used for or for purposes incidental to the conveyance, control or use of electricity supplied or intended to be supplied by an electricity licensee or any other person, and includes a supply installation and any addition, alteration, and repair to an electrical installation, but does not include -\n\n(a) any electric line, supply line or electrical plant of an electricity\n\n(b) any appliance, wire, fitting or apparatus connected to and beyond any electrical outlet which is installed for the purpose of connecting electrical appliances, fittings or apparatuses and at which fixed wiring (cl any appliance, wire, fitting or apparatus which is placed in, on, over or under any premises owned or occupied by a transmission licensee which is not used for the consumption of electricity on the premises or solely for the purposes incidental to the conveyance or control of electricity \"electrical plant\" means any plant, equipment, apparatus or appliance used for, or for purposes connected with, the supply of electricity; \"electrical or supply installation licence\" means a licence granted by the Authority under section 32; \"electrical work\" means any work performed or carried out on any electrical installation and includes the installing, constructing, erecting or repairing thereof or the altering of the structure thereof or the replacing of any part thereof or the adding of any part thereto or the carrying out of any work thereon for the maintenance thereof, but does not include work in (a/ the manufacturing of any electrical installation or the assembling thereof in the course of or in connection with its manufacture for the purpose of producing a new article; or (bl the cleaning or painting of any electrical installation; \"electrical worker\" means any person whose trade or occupation requires or includes the personal performance by him of electrical work or a person who is otherwise competent or qualified to perform personally electrical work; \"electrical worker licence\" means a licence granted by the Authority under \"electricity\" means electrical power when generated, transmitted, supplied or used for any pulpose except the transmission of any communication or \"electricity Licence\" means a licence granted or extended by the Authority \"electricity system\" means a system comprising the transmission system, distribution system and generating stations connected directly or indirectly to the transmission and distribution system; \"generate\" means to produce electricity by means of a generating station for the purpose of giving a supply to any premises or enabling a supply to be so \"high voltage\" means a voltage exceeding lOOOV a.c. or 1500V d.c. between conductors, or 600V a.c. or 900V d.c. between each conductor and Earth; \"low voltage\" means a voltage not exceeding lOOOV a.c. or 1500V d.c. between conductors, or 600V a.c. or 900V d.c. between each conductor and \"Minister\" means the Minister of Energy and Industry in the Office of the \"supply installation\" means the whole of any plant or apparatus in an installation owned or managed by a person for the provision of electricity [other than electricity used for the transmission of any communication or signal) solely for his own use, including any machine supplying mechanical energy to a generator, with all necessary related plant, buildings and land, supply lines and consuming apparatuses, if any; \"transmission system\" means a system of interconnected electric lines, electrical plants and substations used by a transmission licensee to transmit \"transmit\" means to convey electricity by means of a transmission system - (a] from an electrical plant to a transmission substation;or (b] from one electrical plant to another or from one transmission substation to another."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"PART 2"},"heading":{"en":"Administration of Order"},"text":{"en":"(1) The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, by notification published in the Gazette, appoint such person or body as he thinks fit to be the Authority for the purpose of carrying this Order\n\n(2) The Authority shall be responsible for the administration of this Order, either generally or for any particular Part or provision of this Order or for any particular regulations made thereunder, and may in the notification specify the extent of and manner in which that responsibility is to be exercised. Authorised officers"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"PART 2"},"text":{"en":"[I) The Minister may, by notification published in the Gazette, appoint such number of authorised officers to carry into effect any specific provisions of this Order or of any regulations made thereunder.\n\n(2) Every authorised officer appointed under subsection (1) shall - (a1 be furnished by the Authority with an official identification card of his appointment as an authorised officer or officer, as the case may be; and (bl when exercising any power under this Order, on demand, produce the identification card of his appointment to the person affected by the exercise of those powers.\n\nLICENSING OF ACTIVITIES RELATING TO ELECTRICITY Prohibition on unauthorised activities relating to eIectricity"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"PART 3"},"heading":{"en":"Prohibition on unauthorised activities relating to electricity"},"text":{"en":"(1) No person shall engage in the - (a1 generation of electricity; (bl transmission of electricity; or (cl distribution of electricity, unless he is authorised to do so by an electricity licence granted under section 8 or is exempted under section 7. (21 Any person who contravenes subsection (1) is guilty of an offence and liable on conviction to a fine not exceeding $500,000 and, in the case of a continuing offence, to a further fine not exceeding $12,500 for every day or part thereof during which the offence continues after conviction. Application for Iicence, extension or exemption"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART 3"},"heading":{"en":"Application for licence, extension or exemption"},"text":{"en":"(1) An application for an electricity licence, an extension to an electricity licence or an exemption under this Part shall be - (a] made in writing to the Authority and shall be in such form as may be determined by the Authority; and (b] accompanied by the prescribed fee and the payment of such fee, if any, as may be prescribed and such information and documents as may be determined by the Authority.\n\n(2) In determining whether to grant or extend an electricity licence to or for a particular person, the Authority shall consider the following - (a] the ability of that person to finance the carrying on of the particular (b] the experience of that person in carrying on the activity, and his ability to perform the duties which would be imposed on that person under this Order and the electricity licence, if granted; (c] whether or not that person is related to any electricity licensee or any person granted an exemption under section 7."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"PART 3"},"heading":{"en":"Exemption"},"text":{"en":"(11 The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, by order published in the Gazette, exempt any person or class of persons from complying with section 5(1J(a] for any specified period - (a] generally or to such an extent as may be specified in the order; and\n\n(b) unconditionally or subject to such conditions as may be specified\n\n(2) An exemption order shall, unless previously revoked, continue in force for such period as may be specified in the order.\n\n(3) In granting an exemption under this section, the Authority shall act in a manner so as not to discriminate between members of a particular class. 14) Without prejudice to the generality of subsection (l)(b), the conditions imposed under that subsection may require any person carrying on any activity in pursuance of the exemption - (a] to comply with any direction given by the Authority as to such matters as are specified in the exemption order or are of a description so\n\n(b) to do or not to do such things as are specified in the exemption order or are of a description so specified, except in so far as the Authority consents to his doing or not doing them; and (c] to refer for determination by the Authority such questions arising from or under the exemption order as are specified in the order or are of a description so specified. 8th. JUNE, 2017"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"PART 3"},"heading":{"en":"Electricity licences"},"text":{"en":"(1) The Authority may, with the approval of the Minister, grant or extend an electricity licence, unconditionally or subject to such conditions as the Authority may impose and specify in the licence, and revocably or irrevocably as specified therein, authorising any person to -\n\n(a) generate electricity;\n\n(b) transmit electricity;\n\n(c) distribute electricity for or on behalf of a distribution licensee. [2) Every electricity licence granted or extended under this section shall be in writing and shall continue in force, unless revoked or suspended in accordance with this Part, for such period as may be specified in the electricity licence.\n\n(3) An electricity licence may include any restriction or condition (whether or not relating to the activities authorised by the electricity licence] which appears to the Authority to be requisite or expedient. [4) Without prejudice to the generality of subsections (I] and (31, an electricity licence may include any condition - requiring the electricity licensee -\n\n(a) (i] to pay to the Authority a fee on the grant of the electricity licence or to pay to it periodic fees during the currency of the licence or both, of such amount as may be determined by or under the licence; (ii] to enter into any agreement or arrangement on specified terms or on terms of a specified type relating to its trading or operation or for the connection to or use of any electric line or plant owned or operated by the electricity licensee or the other party to the agreement or arrangement; (iii] to observe, with such modification or exemption as may be approved by the Authority, specified codes of practice;\n\n(iv) to maintain specified financial accounting records and prepare financial accounts according to specified principles;\n\n(v) to appoint, at such intervals and on such terms as the Authority may direct, an independent technical auditor for the purposes specified in the condition;\n\n(vi) to prepare for approval by the Authority guidelines regarding the procedures the licensee must follow in the event of any public emergency; (viil to do or not to do such things as are specified in the electricity licence or are of a description so specified; [viii) where the electricity licensee is a transmission licensee, to carry out any work related to the development of a transmission system; and\n\n(ix) where the electricity licensee is a distribution licensee, to carry out any work related to the development of a distribution system or the supply of electricity to any\n\n(b) controlling or fixing prices to be charged for the services provided by a transmission licensee including -\n\n(i) the fixing of prices or the rate of increase or decrease in\n\n(ii) the fiiing of a maximum price or maximum rate of increase or minimum rate of decrease in the maximum price;\n\n(iii) the fixing of an average price or an average rate of increase or decrease in the average price;\n\n(iv) the setting of pricing policies or principles;\n\n(v) the setting of prices with reference to a general price index, the cost of production, a rate of return on assets employed or any specified factor; and\n\n(vi) the setting of prices with reference to the quantity, location, period or other specified factors relevant to the activities authorised by the licence;\n\n(c) in the case of a transmission licensee -\n\n(i) imposing controls and restrictions, directly or indirectly, on the creation, holding or disposal of shares in the licensee or its shareholders or of interests in the undertaking of the licensee or any part thereof; and\n\n(ii) imposing restrictions on the carrying on by the licensee of any trade or business which is not related to the activity which the licensee is authorised by its electricity licence to (dj which provides for any one or more of the conditions specified in the electricity licence to cease to have effect at such times and in such manner and circumstances as may be specified in or determined by or under\n\n(5) The Authority shall in writing notify an applicant for the grant or extension of an electricity licence of its decision to grant or refuse to grant or extend the licence and, in the case of a decision to refuse to grant or extend the licence, the reasons for its decision."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"PART 3"},"heading":{"en":"Restriction on transfer of electricity licence"},"text":{"en":"(1) No electricity licence shall be transferable to any other person without the approval in writing of the Authority.\n\n(2) Any purported transfer of an electricity licence shall be void."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"PART 3"},"heading":{"en":"Modification of conditions of electricity licence"},"text":{"en":"11) Subject to this section, the Authority may modify the conditions of an electricity licence.\n\n(2) The Authority shall not modify any condition of an electricity licence unless the Authority is satisfied that the modification is requisite or expedient.\n\n(3) Before making any modification to the conditions of an electricity licence under this section, the Authority shall give notice to the electricity licensee concerned and other electricity licensees likely to be affected by the proposed modification - (aj stating that the Authority proposes to make a modification in the manner specified in the notice; (bj stating the reasons why the Authority proposes to make the modification, including whether the need for the modification was the subject of a prior representation made by a third party or the electricity licensee concerned; and (cj specifying the period from the date of the giving of the notice (not being less than 28 days) within which written representations with respect to the proposed modification may be made.\n\n(4) Where the Authority receives any written representation under subsection (31, the Authority shall consider such representation and may - [a) reject the representation; or [b) withdraw or amend the proposed modification in accordance with the representation or otherwise, and, in either event, it shall thereupon issue a direction in writing to the electricity licensee concerned requiring that effect be given to the proposed modification specified in the notice, if any, or to such modification as may be subsequently amended by the Authority, within a reasonable time.\n\n(5) Any electricity licensee who is aggrieved by a decision of the Authority under subsection (4) may, within 14 days of the receipt by it of the direction of the Authority, appeal to the Minister whose decision shall be final. The Authority shall not enforce a direction given under subsection (41 -\n\n(6) [a] during the period referred to in subsection (3)[c] unless the electricity licensee concerned consents to the modification referred to under\n\n(3)[a] taking effect before the end of such period; and [b) whilst the appeal of any electricity licensee is under consideration\n\n(7) If no written representation is received by the Authority within the period specified in subsection (3){c] or if any written representation made under that subsection is subsequently withdrawn, the Authority may forthwith carry out the modification as specified in the notice given under that subsection."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"PART 3"},"heading":{"en":"Revocation or suspension of electricity licence"},"text":{"en":"(1) Subsection (2) applies if the Authority is satisfied that - [a] an electricity licensee has gone into compulsory liquidation or voluntary liquidation other than for the purpose of amalgamation or [b] any circumstance specified in an electricity licence that gives rise to the Authority's power to revoke or suspend the licence exists; [c] an electricity licensee has not complied with any direction or requirement issued by the Authority under section 12; [d] an electricity licensee is no longer in a position to operate in conformity with this Order or the conditions of its licence; or [el the public interest or security of Brunei Darussalam requires 8th. JUNE. 2017 12) The Authority may, by notice in writing and without any compensation revoke an electricity licence or suspend an electricity licence for such period as the Authority thinks fit."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"PART 3"},"heading":{"en":"Enforcement"},"text":{"en":"If the Authority is satisfied that an electricity licensee is contravening, or is likely to contravene or has contravened any condition of its electricity licence, any code of practice or other standard of performance applicable to the licensee, any provision of this Order or any direction (including a direction under (a]) issued by the Authority to or applicable to the electricity licensee, the Authority may by notice in writing to the electricity licensee do one or more (a] direct the electricity licensee to do or not do such things as are specified in such direction; (b] require the electricity licensee to provide a performance bond, guarantee or any other form of security on such conditions as the Authority may determine. Codes of practice"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"PART 3"},"text":{"en":"(1) The Authority may issue or approve one or more codes of practice and other standards of performance for the regulation of activities and conduct in the electricity industry. 12) A code of practice issued or approved under this section may be modified by the Authority in accordance with the relevant code of practice by notice published in such manner as will secure adequate publicity.\n\n(3) If any provision in any code of practice issued or approved by the Authority is inconsistent with the regulations, such provision, to the extent of the (a] shall have effect subject to such regulations; or (b] having regard to such regulations, shall not have effect. (41 Any code of practice issued or approved by the Authority under this section shall be deemed not to be subsidiary legislation.\n\n(5) In this section, a reference to code of practice shall include a standard of"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"PART 3"},"heading":{"en":"Direction by Authority"},"text":{"en":"(1) The Authority may give directions for or with respect to codes of practice and other standards of performance and procedures to be observed by licensees and other persons - (a] to ensure the reliability of the supply of electricity to the public; (b] to ensure the security of the electricity system; (c] to maintain the voltage or reactive flow of power through the transmission system and distribution system; or (dl in the interests of public safety.\n\n(2) Any person who fails to comply with any direction given under subsection (1) is guilty of an offence."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"PART 3"},"heading":{"en":"Compliance with codes of practice"},"text":{"en":"(1) Every electricity licensee shall comply with the codes of practice and other standards of performance issued or approved under section 13 and directions given under section 14.\n\n(2) No licensee shall allow electricity to be generated, transmitted or supplied otherwise than in accordance with any applicable code of practice or other standards of performance specified in the conditions of its electricity licence, the regulations or any direction given by the Authority or any regulations made under this Order."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"PART 3"},"heading":{"en":"Exclusion of liability of Authority"},"text":{"en":"Notwithstanding the grant of any electricity licence, the Authority shall not be liable in any circumstance for any loss, damage or cost sustained by any person as a result of any default, negligence, breach or other wrongful act or omission of any electricity licensee or any agent or employee of the electricity Duties of electricity licensees"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"PART 3"},"heading":{"en":"18, Recovery of charges"},"text":{"en":"(1) It shall be the duty of a generation licensee to develop and maintain a reliable, efficient, coordinated and economical system of electricity generation in accordance with the such applicable codes of practice and other standards of performance as may be issued or approved by the Authority under section 13.\n\n(2) It shall be the duty of a transmission licensee - [a) to develop and maintain a reliable, efficient, coordinated and economical transmission system in accordance with such applicable codes of practice and other standards of performance as may be issued or approved by the Authority under section 13; [b] to provide non-discriminatory access to its transmission system for the supply and use of electricity in accordance with this Order and its transmission licence.\n\n(3) It shall be the duty of an electricity licensee to ensure that it will not do or not omit to do any act which will adversely affect, directly or indirectly, the security and stability of the electricity supplied by it or by any other person to of charges"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"PART 3"},"text":{"en":"(1) Subject to subsection (21, if a distribution licensee has good cause to disconnect a consumer from the electricity system, including the failure of the consumer to pay an account, the distribution licensee may disconnect the consumer from the electricity system.\n\n(2) A distribution licensee shall not disconnect the supply of electricity to any residential premises by reason of failure by the consumer to pay an account if the failure occurs through lack of sufficient income of the consumer and of any other person normally resident on the premises supplied [a] the distribution licensee has offered to advise the consumer about optional methods of arranging payment of the account; and [b) the consumer - (i] refuses or fails to accept that offer of advice within the period (being not less than 7 days) specified by the distribution licensee in each case; or\n\n(ii) accepts the offer of advice, but refuses or fails to take any reasonable action to pay the account within the period (being not less than 7 days) specified by the distribution licensee. (31 Subject to this section, if a consumer has not, on the due date, paid all charges due from him to a distribution licensee, the licensee may - [a) in accordance with its licence disconnect that consumer from the distribution system; (bJ discontinue the supply of electricity to the premises, or any other premises occupied by the consumer by such other means as the Iicensee (cJ recover any expenses incurred in so doing from the consumer.\n\n(4) Where a distribution licensee has disconnected the supply of electricity to any premises in consequence of any default on the part of a consumer, the licensee shall reconnect the supply of .electricity to the consumer within a reasonable time if the consumer in default has - (a] made good the default; (b/ paid the reasonable expenses of disconnecting and reconnecting (cJ given such security as the distribution licensee may reasonably\n\n(5) Where a distribution licensee receives any payment from a consumer and the consumer has not, in making the payment, indicated to the distribution licensee the chgrges in respect of which the payment is to be made, the licensee may apportion the payment received to pay such charges in such proportion and manner as it may determine.\n\nMATTERS RELATING TO ELECTRICITY LICENSEES"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"PART 4"},"heading":{"en":"Works by electricity licensee"},"text":{"en":"(1) Subject to the provisions of this Order, a generation licensee, transmission licensee or distribution licensee may, for any purpose connected with the carrying on of the activities authorised by or required under its electricity licence -\n\n(a) install under, over, in, on, along or across any land, premises, street or bridge and inspect, maintain, adjust, repair, alter, replace or\n\n(i) any electric lime or electrical plant;\n\n(ii) any structure for housing or covering any such line or plant; and\n\n(iii) any meter, switch and any other suitable and proper apparatus, for the purpose of leading off service lines and other distributing conductors or of examining, testing, measuring, directing or controlling the supply of electricity or of testing the conditions of the mains and other portions of the (b] execute any work requisite for or incidental to the purposes of any work falling within paragraph (a), including for those purposes - [i] excavating any land, street or drain;\n\n(ii) tunnelling or boring under any land, street, sewer or drain;\n\n(iii) removing or using all earth and materials in or under any land, street, sewer or drain; (iv] erecting, placing or installing equipment, apparatus and other electrical plant in or under any land, building, street or bridge; and [vl erecting, placing or installing poles on any land or street.\n\n(2) A licensee referred to in subsection (1) shall obtain the written approval (a] before issuing a notice under subsection (7); or (b] in the case of an emergency specified in subsection (71, before carrying out any work, if the work to be carried out under this section is in relation to any matter specified in subsection (l)(a](i), (ii) or (iii) which is owned or operated by another electricity licensee.\n\n(3) The right of a licensee to carry out any work in accordance with this section shall have effect notwithstanding any agreement which prohibits the carrying out of the work.\n\n(4) All such works, including the upper surface or covering thereof, shall be constructed of such materials and maintained by the licensee referred to in\n\n(1) in such manner as not to be a source of danger, whether by reason of inequality of surface or otherwise; and when such licensee lays any electric line that is liable to touch any main, pipe, l i e or other service, the conducting portion of the electric line shall be effectually insulated. 15) The licensee referred to in subsection (1) shall pay compensation to any person who suffers any damage or loss of value to his property as a result of any work performed by the licensee under subsection (1) of such amount as may be agreed between the licensee and the person, and such compensation may include an annual payment for the use of any land or immovable property for the licensee's purpose. BRUNEI DARUSSALAM GOVERNMENT GAZE'M'E\n\n(6) The licensee referred to in subsection (1) shall not acquire any right other than that of user only in respect of any land or property under, over, in, on, along or across which the licensee installs any electric line or electrical plant or executes any work under this section.\n\n(7) Except in the case of an emergency arising from any fault in any electric line or electrical plant, the licensee referred to in subsection (1) shall, before entering any land for the purpose specified in subsection (I), give 14 days' written notice to the owner or occupier of the land, stating as fully and accurately as possible the nature and extent of the work to be carried out.\n\n(8) Subject to subsection (91, the owner or occupier of the land who is given a notice under subsection (7) shall comply with the notice and do all things necessary to facilitate the carrying out of the work specified in the notice.\n\n(9) The owner or occupier of the land may, within 14 days of the receipt of the notice referred to in subsection (7), lodge a written objection with the Authority and the Authority shall specify the date by which an inquiry into such objection shall be made. (101 If no objection is lodged within the period specified in subsection (91, the licensee may enter on the land and do all or any of the works specified in the\n\n(11) Where an objection lodged under subsection (9) is not withdrawn before the date fixed for an inquiry into the matter under that subsection, the Authority shall hold an inquiry, giving each party an opportunity to be heard.\n\n(12) Upon the conclusion of the inquiry, the Authority may authorise, either unconditionally or subject to such conditions and stipulations as it thinks fit, the - carrying out of any of the works specified in the notice given under\n\n(13) The decision of the Authority under subsections (2) and (12) shall be final.\n\n(14) The licensee referred to in subsection (1) shall do as little damage as possible in the exercise of the powers conferred by subsection (1) and shall, as soon as practicable, make good any damage done in the exercise of those powers.\n\n(15) Where any dispute arises as to whether a licensee referred to in\n\n(1) has sufficiently made good any damage done in the exercise of the powers conferred by subsection (I), the dispute - (a] may be referred to the Authority by either party; and (b] on such a reference, shall be determined by the Authority whose decision shall be final and conclusive between the parties.\n\n(16) A licensee referred to in subsection (1) shall exercise the powers conferred by subsection (1) in such manner as will secure that nothing which it installs or keeps installed under, over, in, on, along or across any premises, street or bridge becomes a source of danger to the public.\n\n(17) A licensee referred to in subsection (1) shall not, when exercising the powers conferred by subsection (I), be liable for or required to pay any person any fee, charge or expense for the right to enter or use any land or premises.\n\n(18) A licensee referred to in subsection (1) shall not, without the approval in writing of a Government authority or statutory authority, enter or use any land or premises belonging to the Government authority or statutory authority for the purpose of exercising the powers conferred by subsection (1)."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"PART 4"},"heading":{"en":"Savings of wayleave agreements"},"text":{"en":"Nothing in section 1911) and 19) shall - (a/ affect the right of a electricity licensee to enter into an agreement, commonly known as a wayleave agreement, with the owner or occupier of any land for the purpose of laying, placing, carrying or erecting any supply installation or electrical plant used for the supply of electricity on the land; (b/ affect any such wayleave agreement subsisting immediately before the date of commencement of this Order; (c/ affect the right of a electricity licensee to negotiate the use of land or facilities belonging to the State or any other person. Power to fell trees etc."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"PART 4"},"text":{"en":"(1) Where, in the opinion of an electricity licensee, there is at any time danger or suspected danger that any tree or vegetation near the licensee's installation or plant may obstruct or interfere with the supply of electricity or cause damage to such installation or plant, the licensee may cause the tree or vegetation to be felled or dealt with in such other manner as will, in its opinion, avert the danger.\n\n(2) Where any tree or vegetation, which has been felled or dealt with under subsection (I), was in existence before the electricity licensee's installation or plant was placed, erected or installed, the licensee shall, subject to subsections (3) and (41, pay to any person adversely affected such sum as may be agreed between the licensee and the person, or in the absence of agreement, such sum as the Authority may determine.\n\n(3) No further compensation shall be paid for the felling, lopping or clearing of any tree or vegetation where the action is necessary for the maintenance of an electricity licensee's installation or plant and the tree or vegetation has grown or has been allowed to grow since the payment of compensation under subsection (2).\n\n(4) No compensation shall be payable by an electricity licensee under subsection (2) in respect of any tree or vegetation within 20 metres of the centre line of any road constructed or maintained by the Government or by any public authority unless it is proved that the tree or vegetation was in existence prior to the construction of the road.\n\n(5) Where the owner or occupier of any land fells, lops or clears any tree or vegetation adjacent to an electricity licensee's installation or plant, the owner or occupier shall give the licensee 14 days notice in writing of his intention to do so and shall take such reasonable precautions as the licensee may require for the protection of such installation or plant.\n\n(6) If any such owner or occupier fails to give notice under subsection (5) or having given notice fails to take any such reasonable precautions as the electricity licensee may have required, he shall be liable to pay the licensee any cost and expense incurred by the licensee for any damage caused to any such installation or plant, subject to the Authority's approval in the case of any dispute.\n\n(7) If any tree or vegetation is felled, lopped or cleared upon land adjacent to an electricity licensee's installation or plant, it shall be presumed until the contrary is proved that the tree or vegetation was felled, lopped or cleared by the owner or occupier of the land or by his employees or agents acting as such."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"PART 4"},"heading":{"en":"Entry upon premises by electricity licensee for purposes of exploration"},"text":{"en":"(1) Subject to this section and without prejudice to any other right of entry, a person authorised in writing by a transmission or distribution licensee may, at any reasonable time, enter upon and survey any premises for the purpose of ascertaining whether the premises would be suitable for use for any purpose connected with the carrying on of the activities which the licensee is authorised by its electricity licence to carry on.\n\n(2) A person authorised to enter upon any premises under this section shall not demand to do so as of right unless - [a] 7 days notice of the intended entry has been given to the occupier; and [b] if required to do so, he has produced evidence of his authority,\n\n(3) The power to survey premises conferred by this section includes the power to search and bore for the purposes of ascertaining the nature of the subsoil, but works may not be carried out on the premises for this purpose 8th. JUNE, 2017 (a] notice of the proposed works is included in the notice given under (b] where premises are held by any Government authority or statutory authority which objects to the works on the ground that the carrying out of the works would be seriously detrimental to the carrying on of its undertaking, the Minister gives his approval. (41 Where any person exercises any power conferred by this section, the licensee by whom he was authorised shall make good any damage done to the\n\n(5) An electricity licensee shall not, without the approval in writing of a Government authority or statutory authority, authorise any person to enter or use any premises belonging to the Government authority or statutory authority for the purpose of exercising the powers conferred by subsection (1)."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"PART 4"},"heading":{"en":"Entry duringcontinuance of supply"},"text":{"en":"A person authorised by a distribution licensee to enter upon any premises may, at all reasonable times, on the production of some duly authenticated document showing his authority, enter any premises to which a supply of electricity is being given for any of the following purposes - (a] inspecting any electric lime or electrical plant belonging to the (b] ascertaining the register of any electricity meter; (c] removing, inspecting or re-installing any such meter or installing any substitute meter; and (d] carrying out all other works necessary to maintain the supply of"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"PART 4"},"heading":{"en":"Entry during discontinuance of supply"},"text":{"en":"(1) Where - {a] a distribution licensee is authorised by this Order or its electricity licence to disconnect or discontinue the supply of electricity to any premises; /b/ a person occupying premises supplied with electricity by a distribution licensee ceases to require such a supply; or {c/ a person entering into occupation of any premises previously supplied with electricity by a distribution licensee does not require such a any person authorised in writing by the distribution licensee may at all reasonable hours, on production of some duly authenticated document showing his authority, enter the premises for the purposes of disconnecting the supply or removing any electrical plant, electric line or electricity meter, as the case may be.\n\n(2) Subject to section 28, the person so authorised by a distribution licensee shall not enter any dwelling-house in actual occupation without 6 hours previous notice to the occupier, unless the occupier has given his consent to the entry."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"PART 4"},"heading":{"en":"Entry for replacing, repairing or altering electric line or electrical plant"},"text":{"en":"(1) Any person authorised by an electricity licensee in writing may, after 7 days notice to the occupier of any premises or to the owner of any premises which are unoccupied, at all reasonable times, on production of some duly authenticated document showing his authority, enter the premises for the (a] placing a new electric line or electrical plant in the place of or in addition to any existing line or plant which has already been lawfully placed and which belongs to that licensee; or [b] maintaining, inspecting, repairing, removing or altering any such existing line or plant.\n\n(2) In the case of an emergency arising from any fault in any electric line or electrical plant, entry may be made under subsection (1) without the notice required by that subsection, but the notice shall then be given as soon as possible after the occurrence of the emergency."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"PART 4"},"heading":{"en":"Relocation of installation"},"text":{"en":"(1) Where an installation has been laid under or upon any land by an electricity licensee and the owner or occupier of the land desires to use the land in a manner which renders it necessary or convenient to move such installation, the owner or occupier may request the licensee to move the installation accordingly.\n\n(2) An electricity licensee may, at the request of the owner or occupier of any premises under or upon which any installation of the licensee is situated, relocate the installation if the licensee is satisfied that such relocation is reasonable and the owner or occupier complies with such conditions as the licensee may impose, including conditions relating to the payment by the owner or occupier of all costs and expenses necessary for the relocation. (31 Where an installation has been laid under or upon any land by an electricity licensee and the installation is no longer in use by the occupier of the land or any other person for the purpose of the transmission or supply of 8th. JUNE. 2017 electricity, the licensee may at its own volition, or at the reasonable request of the owner of the land, remove the installation from the land at the expense of the electricity licensee.\n\n(4) For the purposes of this section, \"owner\" includes any person having a leasehold interest in the land or premises with an unexpired term of not less than 7 years."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"PART 4"},"heading":{"en":"Electrical plant not fixtures and not subject to distress"},"text":{"en":"Any electrical plant, electric line, electricity meter, appliance, accessory, fitting and appurtenance owned or let for hire or lent to a consumer by an electricity licensee and which has been affixed or fastened to any part of the [a] shall continue to remain the property of that licensee and shall be deemed not to be a fixture, and shall not vest in the owner of the premises; and (b] shall not be subject to distress or be liable to be taken in execution under process of any court or any proceedings in bankruptcy against the person in whose possession it is. Power to discontinue supply of electricity in emergency etc."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"PART 4"},"text":{"en":"(1) Where an electricity licensee is of the opinion that immediate action is necessary on the occurrence of any emergency, in the interest of public safety or in order to avoid undue interference with the efficient supply of electricity to other consumers or for such other reasons affecting public interest, the licensee - (a] may forthwith discontinue the supply of electricity to any person; [bl shall immediately thereafter give notice in writing of the discontinuance to the person.\n\n(2) An electricity licensee shall not be liable for any loss or damage caused to any person by such discontinuance of the supply of electricity to the person."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"PART 4"},"heading":{"en":"Emergency plans"},"text":{"en":"(1) The Authority may require an electricity licensee to prepare and file with the Authority such emergency plans in accordance with, and as may be specified in its licence.\n\n(2) The Authority may, with, the approval of the Minister, direct an electricity licensee to implement an emergency plan prepared by that licensee on one or more occasions and with such modifications as the Minister may consider"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"PART 4"},"heading":{"en":"Sharing of installation, plant or system"},"text":{"en":"(1) The Authority may direct any electricity licensee to co-ordinate and cooperate, in such manner and on such terms as the Authority may specify, with any other person, in the use or sharing of any installation, plant or system, or part thereof, used for supply of electricity.\n\n(2) Any person who fails to comply with any direction under subsection (1) is guilty of an offence. Precautions in execution of work"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"PART 4"},"text":{"en":"The execution of work by an electricity licensee under this Order which may affect any street, river, canal, or other waterway or any system of irrigation, drainage or water supply or any electricity, harbour works or other public or private works, and the erection of any installation or plant used for electricity whether over, on or under the ground shall be car;?ed out in a lawful manner having regard to the safety of any person or property.\n\nELECTRICAL AND SUPPLY INSTALLATIONS, CABLE DETECTION WORK AND ELECTRlCAL WORKERS Licence required for use or operation of electrical or supply installation etc."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"PART 5"},"text":{"en":"11) No person shall 2 (a] use, work or operate or permit to be used, worked or operated any electrical or supply installation; or (bj supply to or for the use of any other person electricity from any electrical or supply installation, except under and in accordance with the terms of an electrical or a supply installation licence granted by the Authority under this section authorising such use, work, operation or supply.\n\n(2) An electrical or a supply installation licence may be granted under this section on the payment of such fee, if any, as may be prescribed.\n\n(3) An electrical or a supply installation licence shall not be transferred without the approval of the Authority.\n\n(4) An electrical or a supply installation licence shall be subject to such conditions as may be prescribed and to such further conditions, if any, as may be imposed and endorsed on the licence by the Authority.\n\n(5) An electrical or a supply installation licence may be for such period as the Authority may approve.\n\n(6) In every electrical or supply installation licence, there shall be specified as may be appropriate -\n\n(a) the installation area;\n\n(b) the declared voltage frequency and the variations permitted\n\n(c) such other matters as the Authority may consider desirable.\n\n(7) The Authority may, in its discretion, require that, before the grant of any electrical or supply installation licence, such security as it may specify shall be furnished to ensure the due observance of the conditions of the licence and of the provisions of this Order.\n\n(8) An electrical or a supply installation licence may be surrendered by the licensee to the Authority for cancellation if the electrical or supply installation is no longer required to be used.\n\n(9) Where the licensee wishes to operate the electrical or supply installation after the surrender of the licence, the installation shall be treated in all respects as if it were a new electrical or supply 'installation."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"PART 5"},"heading":{"en":"Notice to electricity licensee to cut off supply"},"text":{"en":"(1) Where any person operates an electrical or a supply installation without an electrical or a supply installation licence -\n\n(a) the Authority may by written notice direct any electricity licensee to forthwith discontinue the supply of electricity to that electrical or supply installation; and\n\n(b) the electricity licensee shall, upon receipt of the notice, immediately comply with the notice. 12) Where the Authority has directed an electricity licensee to discontinue a supply of electricity under subsection (11, the licensee may discontinue the supply until all expenses incurred by the licensee are fully paid by the person operating the electrical or supply installation."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"PART 5"},"heading":{"en":"Supply lines and other apparatus on State land"},"text":{"en":"(1) Subject to the approval of the Commissioner of Land and to such conditions as he may impose, an electrical or a supply installation licence may authorise the licensee to lay, place or carry on, under or over any State land to the extent and in the manner specified in the licence, such supply lines, and to erect and maintain in or on the State land such posts and other apparatuses as may, in the opinion of the Authority, be necessary or proper for the purposes of the electrical or supply installation.\n\n(2) Any authorisation under subsection (1) may be given or added to at any time during the currency of the licence by endorsement thereon.\n\n(3) All apparatuses placed in or upon any State land which is not removed therefrom within 6 months, or such longer period as the Commissioner of Land may permit, after the expiration or earlier determination of the licence under the authority of which the apparatus was so placed, shall vest in and become the property of the Government."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"PART 5"},"heading":{"en":"Existing electrical or supply installation"},"text":{"en":"All electrical and supply installations which have been operated or the construction of which has been completed or has begun on or before the date of commencement of this Order shall be subject to this Order."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"PART 5"},"heading":{"en":"Exemption of certain electrical or supply installation"},"text":{"en":"The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, by notification published in the Gazette, exempt from all or any of the provisions of this Part - [a) any electrical or supply installation owned and operated by an electricity licensee, the Government or any statutory authority; [b) any electrical or supply installation used exclusively for domestic purposes; and [c) such other electrical or supply installations as the Authority may consider desirable."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"PART 5"},"heading":{"en":"Control by electrical worker"},"text":{"en":"(1) A person granted an electrical or a supply installation licence shall employ or appoint such class or classes of electrical workers as the Authority may direct to operate or to be in charge of or to control any electrical or supply installation and no other person shall operate or be in charge of or control the electrical or supply installation.\n\n(2) Any person who contravenes subsection (1) is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 12 months or both and, in the case of a continuing offence, to a further fine not exceeding $250 for every day or part thereof during which the offence continues after conviction. of electrical or supply installation"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"PART 5"},"heading":{"en":"Inspection of electrical or supply installation"},"text":{"en":"(1) A person granted an electrical or a supply installation licence shall cause all electrical or supply installations owned or operated by him to be inspected at such intervals as the Authority may consider necessary. (21 An inspection referred to in subsection 111 shall be carried out by such class or classes of electrical workers as,the Authority may direct.\n\n(3) On completion of the inspection, a certificate as to the fitness of the electrical or supply installation for licensing purposes shall be issued by the electrical worker who carried out the inspection. of use to specified purpose"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"PART 5"},"heading":{"en":"Restriction of use to specified purpose"},"text":{"en":"(1) A person granted an electrical or a supply installation licence who is, by the conditions of his licence, restricted to using or supplying electricity for specified purposes only, shall not use or supply electricity for any purpose other than those specified. (21 Any person who contravenes subsection (1) is guilty of an offence."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"PART 5"},"heading":{"en":"Procedure in case of defect in electrical or supply installation"},"text":{"en":"(1) Every electrical worker appointed to operate or to be in charge of or to control any electrical or supply installation and every person granted an electrical or a supply installation licence who becomes aware of a defect in any electrical or supply installation shall forthwith make good or remove the defect or make a report thereon to the Authority.\n\n(2) Where a report is made to the Authority under subsection (I), the Authority may by notice -\n\n(a) posted on the premises where the electrical or supply installation is installed or working; or (bj served on the person granted an electrical or a supply installation licence or the electrical worker who is appointed to operate or to be in charge of or to control the electrical or supply installation, as the case may be, ' require the defect to be made good or removed within such period as may be specified in the notice, and the electrical or supply installation shall not be operated or used after the expiration of that period unless the defect has been made good or removed to the satisfaction of the Authority.\n\n(3) If the Authority is of the opinion that the defect is likely to cause immediate danger, the Authority may, by notice posted or served in the manner specified in subsection (21, forthwith suspend the operation and use of the electrical or supply installation until the defect is made good or removed, and the electrical or supply installation shall not be operated or used so long as the notice of suspension remains in force.\n\n(4) The Authority shall not be liable for the loss or damage caused to any (a/ by the suspension of the operation and use of any electrical or supply installation under this section; or (bj by the suspension or revocation of an electrical or a supply installation licence under section 41. I\n\n(5) Any person who contravenes subsection (I), (2) or (3) is guilty of an"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"PART 5"},"heading":{"en":"Suspension and revocation of electrical or supply installation licence"},"text":{"en":"An electrical or a supply installation licence may at any time be suspended or revoked by the Authority - (a1 on breach of any of the conditions of the licence or for non-compliance with any of the provisions of this Order; (b/ in default of payment of any money due; or (cj if the licensee ceases to work or operate any electrical or supply installation in respect of which the licence was granted."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"PART 5"},"heading":{"en":"Entry upon premises"},"text":{"en":"(1) Subject to subsection (21, an authorised officer may, in the performance of his functions and duties under this Order, enter upon any premises in or upon which any electrical or supply installation may be, at all reasonable hours of the day and at any time when the electrical or supply installation is in operation.\n\n(2) No person shall be obliged to admit into his premises any person purporting to be an authorised officer except upon production of identification card or badge."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"PART 5"},"heading":{"en":"Authority not liable for operation of electrical or supply installation"},"text":{"en":"Notwithstanding the grant of an electrical or a supply installation licence, the Authority shall not be responsible for the operation or maintenance of any electrical or supply installation or for any injury to any person or damage to anything by reason of operating or omitting to operate or maintaining or omitting to maintain any electrical or supply installation."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"PART 5"},"heading":{"en":"Cable detection work to be carried out before earthworks"},"text":{"en":"(1) Subject to subsection (21, no person other than an electricity licensee shall commence or carry out, or cause or permit the commencement or carrying out of, any earthworks within the vicinity of any low voltage electricity cable which belongs to or which is under the management or control of an electricity 'I licensee unless the person has caused cable detection work to be carried out by a licensed cable detection worker.\n\n(2) Nothing in subsection (1) shall prohibit a person from commencing or carrying out any earthworks where he has reasonable cause to believe that it is necessary to do so in the interest of public or private safety except that the person shall, not more than 7 days after the earthworks have been commenced or carried out, give to the electricity licensee notice in writing stating the nature and extent of those earthworks.\n\n(3) No person other than a licensed cable detection worker or an electricity licensee shall commence or carry out any cable detection work,within the vicinity of any low voltage electricity cable belonging to or under the management or control of the licensee where such cable detection work is commenced or carried out in connection or combination with or in relation to any earthworks carried out or to be carried out.\n\n(4) Any person who contravenes subsection (11 or (3) is guilty of an offence ' and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 12 months or both."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"PART 5"},"heading":{"en":"Carrying out of earthworks within vicinity of high voltage electricity cable"},"text":{"en":"(1) Subject to this section, no person other than an electricity licensee shall commence or carry out, or cause or permit the commencement or carrying out of, any earthworks within the vicinity of any high voltage electricity cable which belongs to or which is under the management or control of an electricity licensee unless the person - (a] has given to the electricity licensee not less than 7 days notice in writing of the date on which it is proposed to commence the earthworks; (b] has obtained from the electricity licensee the necessary information on the location of such high voltage electricity cable and has consulted the electricity licensee on the steps to be taken to prevent the high voltage electricity cable from damage while the earthworks are being carried out; and (cj has caused cable detection work to be carried out by a licensed cable detection worker in order to confirm the location of the high voltage electricity cable. BRUNEl DARUSSALAM GOVERNMENT GAZETTE\n\n(2) No person other than a licensed cable detection worker shall commence or carry out any cable detection work within the vicinity of any high voltage electricity cable which belongs to or which is under the management or control of an electricity licensee.\n\n(3) The Authority may, if it thinks fit, modify the period for which a notice under subsection [l)(a) is to be given to an electricity licensee. (41 It shall be the duty of the person who carries out any earthworks referred to in subsection (1) to -\n\n(a) comply with all reasonable requirements of the electricity licensee for the prevention of damage to the high voltage electricity cable;\n\n(b) ensure that reasonable precautions are taken when carrying out such earthworks to prevent any damage to the high voltage electricity cable; and\n\n(c) allow the electricity licensee reasonable access to the work site for the purpose of inspecting or taking any necessary measures to protect the high voltage electricity cable.\n\n(5) It shall be the duty of the electricity licensee to whom a notice under (lJ(a) has been given to -\n\n(a) promptly inform the person who has given him the notice of the location of the high voltage electricity cable and to provide the person with any other information as may be necessary to enable him to ascertain the exact location of the high voltage electricity cable;\n\n(b) advise the person who has given him the notice on the precautions to be taken to prevent damage to the high voltage electricity cable; and\n\n(c) take all such measures at the work site as may be reasonable and necessary for the protection of the high voltage electricity cable from damage and, in so doing, the electricity licensee shall have regard to the potential risks and dangers that can arise from any damage to the high voltage electricity cable.\n\n(6) Nothing in subsection (1) shall prohibit a person from commencing or carrying out any earthworks where he has reasonable cause to believe that it is necessary to do so in the interest of public or private safety except that the person shall, not more than 7 days after the earthworks have been commenced or carried out, give to the electricity licensee notice in writing stating the nature and extent of those earthworks. 8th. JUNE, 2017\n\n(7) Any person who contravenes subsection (I) or (4) is guilty of an offence and liable on conviction to a fine not exceeding. $100,000, imprisonment for a term not exceeding 5 years or both.\n\n(8) Any person who contravenes subsection (2) is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 12 months or both.\n\n(9) Subject to subsection (lo), in any proceedings for an offence under subsection (71, it shall be a defence for the person charged to prove that -\n\n(a) he took all reasonable steps to discharge his duty under\n\n(1) or (41, as the case may be; or\n\n(b) he took all reasonable precautions and exercised all due diligence to avoid the commission of the offence. (101 If in any proceedings for an offence under subsection (71, the defence involves acting on information supplied by an electricity licensee, the person charged shall not, without leave of the court, be entitled to rely on that defence unless, within 14 clear days before the hearing, he has sewed on the prosecutor a notice in writing giving such information as was then in his possession identifying or assisting in the identification of the person who supplied him with the Powers of Autbority in relation to cable detection work"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"PART 5"},"heading":{"en":"Powers of Authority in relation to cable detection work"},"text":{"en":"(1) The Authority may -\n\n(a) grant a cable detection work licence permitting a person to perform such cable detection work as is specified in the licence and suspend, cancel, alter, extend, renew or replace any such licence;\n\n(b) classify any cable detection work licence in such manner as it may (cj specify the nature of the cable detection work in respect of which a cable detection work licence is granted and restrict such work to any type or class of cable detection work; (dl specify the circumstances or manner in which licensed cabIe detection workers may perform or carry out cable detection work;\n\n(e) impose any terms, conditions or restrictions on any cable detection work licence; , BRUNEI DARUSSALAM GOVERNMENT GAZETTE (f/ require any electricity licensee to conduct approved courses of training, including refresher courses, and provide for examinations for cable detection workers; and (g/ keep a register of licensed cable detection workers.\n\n(2) No person other than a licensed cable detection worker shall be entitled to recover in any court any charge, fee or remuneration for any cable detection work carried out by the person. Licensing of electrical worker"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"PART 5"},"text":{"en":"(I] Subject to subsection (21, no person shall - (a] carry out or caused to be carried out any electrical work, unless he holds a valid electrical worker licence; (b] advertise or otherwise holds himself out as an electrical worker, or as a licensed electrical worker, or as a person competent or qualified by any written law to perform or carry out electrical work, unless he holds a valid electrical worker licence; or (c] engage knowingly any person who is not a licensed electrical worker to carry out any electrical work.\n\n(2) The Authority may - I (a] issue an electrical worker licence permitting a person to cany out such electrical work as is specified in the licence and suspend, cancel, alter, extend, renew or replace any such licence; (b/ classify any electrical worker licence in such manner as it may (c] specify the nature of the electrical work in respect of which an electrical worker licence is issued and restrict such work to any type or class I of electrical work or any type or class of electrical installation; (dl specify the circumstances or manner in which licensed electrical workers may carry out electrical work; or (el attach any exemption to or impose any condition on any electrical\n\n(3) Any person who contravenes subsection (1) is guilty of an offence.\n\n(4) Notwithstanding any provision in this section, but subject to any other written law, it shall not be unlawful for - 8th. JUNE, 2017\n\n(a) a person to replace any lamp that is connected in his own electrical\n\n(b) a person to replace any fuse in his own electrical installation similar to that of a household;\n\n(c) an officer or employee of the Authority to carry out personally any electrical work in the course of his employment or in the discharge of his duties as such officer or employee;\n\n(d) the Authority to do any act or thing on or in connection with its own electrical installation; (el a person, other than an electrical worker, whose trade or occupation normally includes the performance of work on any appliance, plant or machinery driven, or operated by, or incorporating any electrical installation, to carry out that work in the normal course of his trade or occupation or for purposes incidental thereto, so long as he does not cany out work on any part or circuit which is, or may be, connected to a source of electricity supply; and (fj a trained person to carry out any work in accordance with the written instructions of the licensed electrical worker in charge of the relevant electrical installation.\n\n(5) In subsection (4)(f), a \"trained person\" means any employee who is\n\n(a) recognised by his employer and the licensed electrical worker in charge of the relevant electrical installation to have the necessary knowledge and experience to avoid danger; and I (b] capable of carrying out the work specified in the written instructions of the licensed electrical worker. Offences relating to electrical or supply inslallations"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"PART 6"},"heading":{"en":"Offences relating to electrical or supply installations"},"text":{"en":"(1) Any person who supplies electricity to any premises without an electrical or a supply installation licence is guilty of an offence and liable on conviction to a fine not exceeding $50,000, imprisonment for a term not 3 years or both.\n\n(2) Any person who wilfully tampers with or adjusts any electrical or supply installation or any part thereof so as to cause or to be likely to cause , danger to human life or damage to any property is guilty of an offence and liable on conviction to imprisonment for a term not exceeding 5 years.\n\n(3) Any person who, by rash or negligent act or omission committed or omitted in respect of any electrical or supply installation or any part thereof under his control, causes hurt to any person or damage to any property is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 3 years or both.\n\n(4) Any person who contravenes section 32(1) is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 3 years or both and, in the case of a continuing offence, to a further fine not exceeding $250 for every day or part thereof during which the offence continues after conviction.\n\n(5) Any licensee of a supply installation who without express authority from the Authority supplies electricity or lays down any supply line or constructs any electrical works outside the installation area specified in his licence is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 3 years or both. (61 Any such unauthorised line or works may be removed by order of the Authority, and the reasonable cost of such removal may be recovered from the\n\n(7) Any licensee of an electrical or a supply installation who, without lawful excuse, fails to comply with any condition in his licence is guilty of an"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"PART 6"},"heading":{"en":"Restoration of supply without consent"},"text":{"en":"Any person who, without the consent of an electricity licensee, restores a supply of electricity to any premises where such supply has been discontinued by the electricity licensee in the exercise of its powers under this Order is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 3 years or both and, in the case of a continuing offence, to a further fine not exceeding $250 for every day or part thereof during which the offence continues after conviction."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"PART 6"},"heading":{"en":"Damage to property of electricity licensee"},"text":{"en":"(1) Any person who wilfully removes, destroys or damages any electricd plant or electricity cable in the transmission network belonging to or under the management or control of an electricity licensee or hinders or prevents the electrical plant or electricity cable from being used or operated in the manner in which it is intended to be used or operated is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment For a term not exceeding 3 years or both.\n\n(2) Notwithstanding subsection (I), any person who, in the course of carrying out any earthworks, damages or suffers to be damaged any high voltage electricity cable in the transmission network belonging to or under the management or control of an electricity licensee is guilty of an offence and liable on conviction to a fine not exceeding $1 million, imprisonment for a term not exceeding 5 years or both.\n\n(3) Where an offence under subsection (2) is committed by any person acting as the agent or servant of another person, or being otherwise subject to the supervision or instructions of another person for the purposes of any employment in the course of which the offence was committed, that other person shall, without prejudice to the liability of the first-mentioned person, be liable under that subsection in the same manner and to the same extent as if he had personally committed the offence unless he proves to the satisfaction of the court that the offence was committed without his consent or connivance or that it was not attributable to any neglect on his part.\n\n(4) Any person may apprehend any other person if the other person within his view commits an offence under this section and shall, on such apprehension without unreasonable delay, hand over the person so apprehended to a police\n\n(5) In any proceedings for an offence under subsection (21, it shall be a defence for the person charged to prove that he took all reasonable precautions and exercised all due diligence to avoid the commission of the offence.\n\n(6) In any proceedings for an offence under subsection (21, the defence involves acting on information supplied by a licensed cable detection worker, the person charged shall not, without leave of the court, be entitled to rely on that defence unless he has, within 14 clear days before the hearing, served on-the prosecutor a notice in writing giving such information as was then in his possession identifying or assisting in the identification of the licensed cable detection worker."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"PART 6"},"heading":{"en":"Falsely pretending to be employee of Authority or electricity licensee"},"text":{"en":"Any person who seeks to obtain entry to any premises by falsely pretending to be an employee of the Authority or an electricity licensee is guilty of an"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"PART 6"},"heading":{"en":"Unauthorised use of electricity"},"text":{"en":"(1) Any person who -\n\n(a) dishonestly or fraudulently abstracts, uses or consumes, or dishonestly or fraudulently diverts or causes to be diverted, any electricity an electricity licensee; [b) without the written consent of the electricity licensee, supplies for consideration any other person with any electricity supplied to him for any purpose by the electricity licensee; or [c) alters or tampers with any meter supplied by an electricity licensee, is guilty of an offence and liable on conviction to a f i e not exceeding $50,000, imprisonment for a term not exceeding 3 years or both and, in the case of a continuing offence, to a further fine not exceeding $250 for every day or part thereof during which the offence continues after conviction.\n\n(2) Where any person is prosecuted for an offence under subsection (lJ[b) -\n\n(a) the possession by him of any device for altering the index of any meter or for preventing any meter from duly registering the quantity of electricity supplied by an electricity licensee; [b) the existence of any hole on the meter cover of any meter supplied by an electricity licensee; or\n\n(c) the existence of any damage to the seal which is fastened to the outer cover of any meter to ensure that the cover is not removed, opened, dislodged or otherwise tampered with, when the meter is in the custody or under the control of the person, shall be prima facie evidence that the person has altered or tampered with the meter."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"PART 6"},"heading":{"en":"Obstructing licensee in performance of duties"},"text":{"en":"Any person who at any time molests, or without cause, hinders or obstructs, any employee, agent or contractor of an electricity licensee in the performance of his duties or anything which he is respectively authorised, empowered or required to do under this Order is guilty of an offence."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"PART 6"},"heading":{"en":"Making of False statement"},"text":{"en":"(1) Any person who, when giving information to the Authority or making any application under or for the purposes of any provision of this Order, makes any statement which he knows to be false in a material particular, or who recklessly makes any statement which is false in a material particular, is guilty of an offence.\n\n(2) Any person who - [a) wilfully or fraudulently procures or attempts to procure for himself or for any other person any licence under this Order by making or producing or causing to be made or produced any false or fraudulent representation or declaration either verbally or in writing; or\n\n(b) knowingly aids or assists therein, is guilty of an offence."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"PART 6"},"heading":{"en":"Jurisdiction of court"},"text":{"en":"Notwithstanding any provision to the contrary in the Criminal Procedure Code (Chapter 71, a Court of a Magistrate shall have jurisdiction to try any offence under this Order and shall have power to impose the full penalty or punishment in respect of any offence under this Order. by body corporate"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"PART 6"},"heading":{"en":"Offences by body corporate"},"text":{"en":"Where an offence under this Order has been committed by a company, firm, society or other body of persons, any person who, at the time of the commission of the offence, was a director, manager, secretary or other similar officer or a partner of the company, firm, society or other body of persons or was purporting to act in any such capacity, is guilty of that offence and liable to be proceeded against and punished accordingly unless he proves that -\n\n(a) the offence was committed without his consent or connivance; and (b] he had exercised all such due diligence to prevent the commission of the offence as he ought to have exercised, having regard to the nature of his functions in that capacity and to all the circumstances."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"PART 6"},"heading":{"en":"General penalties"},"text":{"en":"Any person guilty of an offence under this Order for which no penalty is expressly provided is liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 12 months or both and, in the case of a continuing offence, to a further fine not exceeding $250 for every day or part thereof during which the offence continues after conviction. of offences"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"PART 6"},"text":{"en":"(I] The Authority may, in its discretion, compound any offence under this Order which is prescribed as a compoundable offence by collecting from a person reasonably suspected of having committed the offence a sum not exceeding $2,000. (21 The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, make regulations to prescribe the offences which may be compounded.\n\n(3) On payment of such sum of money, no further proceedings shall be taken against such person in respect of the offence. Serious accidenls to be reported and investigated"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"PART 7"},"heading":{"en":"Serious accidents to be reported and investigated"},"text":{"en":"11) When any accident causing or resulting in loss of life or hurt to any person or serious damage to property has occurred in connection with any electrical or supply installation, or any other instauation, the owner of the premises concerned and the person granted a licence under Part 5 for the installation Shall - (01 report the accident to the Authority by the quickest means available; and (bj subsequently with the least possible delay, report in writing to the Authority the facts of the matter so far as the facts are known.\n\n(2) Any authorised officer shall as soon as practicable after receipt of the first report - (01 visit the place where the accident occurred; (bl make a preliminary investigation of the circumstances; (cj record in writing his findings upon such investigation; (dl forward his report to the Authority; and (el if there has been any loss of life or there is reason to believe that any person has been seriously injured, send a copy of his findings to the Public Prosecutor.\n\n(3) In the event of loss of life or grievous hurt to any person due to any accident arising from the use or operation of or caused by any electrical or supply installation or other installation, no alteration or addition shall, without the approval of the Authority, be made to any part of the installation which may have contributed towards the cause of the accident or to the site of the accident until investigations have been completed.\n\n(4) Nothing in subsection 13) shall operate to interfere with rescue work or other work necessary for the general safety of life or property.\n\n(5) If upon a preliminary investigation under subsection 12)(bj - (01 it appears to the Authority that there is reason to believe that the accident was due to any failure to comply with the provisions of this Order or due to neglect to obey any lawful order given by the Authority; or\n\n(b) the authorised officer investigating the accident is satisfied that the accident might have been prevented if proper precautions had been taken and observed in the operation or working of the electrical or supply installation or other installation, the Authority shall hold an inquiry into the nature and cause of the accident with the assistance, if considered necessary by the Authority, of one or more persons of electrical or other special skill or experience to he nominated by the Authority as assessors.\n\n(6) At the conclusion of the inquiry held under subsection (51, a copy of the findings taken at the inquiry together with the opinion of the Authority shall be forwarded to the Public Prosecutor.\n\n(7) Any person who, without lawful excuse, contravenes subsection (1) or\n\n(3) is guilty of an offence."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"PART 7"},"heading":{"en":"Powers of arrest"},"text":{"en":"(1) Any police officer or any person authorised in writing by the Authority generally or in any particular case may arrest any person committing within his view or who he has reason to believe has committed any offence punishable under this Order if -\n\n(a) the name and address of the person are unknown to him;\n\n(b) the person declines to give his name and address; or\n\n(c) there is reason to doubt the accuracy of the name and address (21 A person arrested under this section, unless his name and address are correctly ascertained, shall withim 48 hours of the arrest he brought before a Magistrate or be released upon signing a bond with or without surety to appear before a Magistrate.\n\n(3) The person brought before a Magistrate under subsection (31 may -\n\n(a) be ordered to be detained until he can be tried; or\n\n(b) if required by the Magistrate, be released upon signing a bond, with or without surety, to appear before a Court of a Magistrate."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"PART 7"},"heading":{"en":"Appeal to Minister"},"text":{"en":"(1) A person aggrieved by - (aj any decision of the Authority in the exercise of any discretion vested in it by or under this Order; (bj anything contained in any code of practice or standard of performance issued or approved by the Authority under section 13; or [cj any direction issued by the Authority under this Order, may appeal to the Minister, together with adequate details of the grounds for the\n\n(2) Unless otherwise provided in this Order, an appeal under subsection (1) shall be lodged within 14 days of the receipt of the decision or direction of, or the issue or approval of the code of practice or standard of performance by, the\n\n(3) Any person who has lodged an appeal under subsection (1) shall provide such information as may be required by the Minister in such manner and within such period as may be specified by the Minister.\n\n(4) Unless - (a] otherwise provided in this Order; or (bj the appeal is against the imposition or the amount of a financial penalty, an appeal under subsection (1) shall not suspend the effect of the decision, direction, code of practice or standard of performance to which the appeal relates.\n\n(5) The Minister may determine an appeal under this section by confirming, varying or reversing any decision or direction of the Authority or by amending any code of practice or standard of performance issued or approved by\n\n(6) The decision of the Minister shall be final. of documents"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"PART 7"},"heading":{"en":"Service of documents"},"text":{"en":"[I) Any notice, order or document required or authorised by this Order to be given or served on any person, and any summons issued by a court in connection with any offence under this Order may be served on the person - [aj by delivering it to him or to some adult member or employee of his family at his last known place of residence; (bj by leaving it at his usual or last known place of residence or business in an envelope addressed to him; (cl by affixing it to some conspicuous part of his last known place of residence; (dl by sending it by registered post addressed to him at his usual or last known place of residence or business; or (el where the person to be served is a body corporate -\n\n(i) by delivering it to the secretary or other like officer of the body corporate at its registered or principal office; or\n\n(ii) by sending it by registered post addressed to the body corporate at its registered or principal office.\n\n(2) Any notice, order, document or summons sent by registered post to any person in accordance with subsection (1) is deemed to be duly served on the person at the time when the notice, order, document or summons would, in the ordinary course of post, be delivered and in proving service of the notice, order, document or summons, it shall be sufficient to prove that the envelope containing the same was properly addressed, stamped and posted by registered post."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"PART 7"},"heading":{"en":"Recovery of fees and penalties"},"text":{"en":"Any fee or financial penalty to be paid to the Authority under this Order may be recovered by it in any court of competent jurisdiction as if it were a simple contract debt. Liability of electricity licensee due to conlinuous interruption of electricity supply"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"PART 7"},"heading":{"en":"Liability of electricity licensee due to continuous interruption of electricity"},"text":{"en":"(1) An electricity licensee shall be liable to pay compensation to any person who is affected by an interruption of electricity supply, of a sum calculated in accordance with such formulae, and compensated in such form and manner, as the Authority may determine. 12) Subsection (1) applies where - [a] the person is carrying on a trade, profession or business; and [b] the interruption of electricity supply -\n\n(i) exceeds such continuous period as the Authority may determine; and\n\n(ii) resulted from the incapacity of the electricity licensee.\n\n(3) For the avoidance of doubt, the acceptance of any compensation under\n\n(1) shall be without prejudice to the person's right to bring a civil action against the electricity licensee for any loss or damage caused to any person or his property by such interruption of electricity supply to the person."}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"PART 7"},"heading":{"en":"Keeping of register"},"text":{"en":"(1) The Authority shall, at such Iocation and in such form as it may determine, maintain a register for the purposes of this Order. [2) Subject to any direction under subsection (31, the Authority shall cause to be entered in the register -\n\n(a) the provisions of every licence or exemption granted to any person Part 3 and the details of every licence or exemption revoked;\n\n(b) the details of any modification to the conditions of an electricity\n\n(c) any other matters as the Authority thinks fit (31 If it appears to the Minister that the entry of any provision or detail in the register would be against the public interest, he may direct the Authority not to make the entry in the register.\n\n(4) The register shall be available for inspection by the public during such hours and subject to the payment of such fee, if any, as may be prescribed by the"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"PART 7"},"heading":{"en":"Effect of direction"},"text":{"en":"(1) The obligation to comply with any direction made by the Authority is a duty owed to any person who may be affected by a contravention of it.\n\n(2) Where a duty is owed by virtue of subsection (1) to any person, any breach of the duty which causes that person to sustain loss or damage shall be actionable at the suit or instance of that person.\n\n(3) In any proceedings brought against any person under subsection (21, it shall be a defence for him to prove that he took a11 reasonable steps and exercised a11 due diligence to avoid contravening the relevant direction.\n\n(4) Without prejudice to any right which any person may have under subsection (2) to bring civil proceedings in respect of any contravention of any relevant direction, compliance with any such direction shall be enforceable by civil proceedings by the Authority for an injunction or for any other appropriate relief. 8th. JUNE, 2017"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"PART 7"},"heading":{"en":"Regulations"},"text":{"en":"(1) The Minister may, with the approval of His Majesty the Sultan and Yang Di-Pertuan, make regulations for or in respect of every purpose which is considered by the Minister necessary or convenient to be prescribed for carrying out the provisions of this Order.\n\n(2) Without prejudice to the generality of subsection (11, the Minister may make regulations for or in respect of all or any of the following matters - (a] the prescribing of purposes for which the supply of electricity may be used; [bl the prevention of misuse or use of electricity; (cl the prevention of misuse of, or damage to, apparatus and works belonging to a licensee in connection with the generation, transmission or supply of electricity; (dl the regulation and use oi electricity meters and the prohibition of interference with, or damage to such meters or seals affixed thereto; (el the prohibition of interference with, or damage to, electric appliances supplied by a licensee and plates or marks thereon; (fl the regulation of the installation of electrical installations and alterations thereto and the sublnission of plans and specifications in respect (g] the prescribing of materials of which conduits, pipes, cables and other apparatus and fittings for use in connection with the supply of electricity shall be made, and of the size, shape, fitting, arrangement, connection, workmanship, examination, testing, position and method of cleaning them; (hl the prescribing of the types of electric appliances to be used and the prohibition of the use of certain types thereof; (il the regulation of the installation of electric appliances and the removal or transfer thereof; (jl the prescribing of the methods of charging consumers for electricity in the event of any meter becoming out of order; (kl the prescribing of conditions applicable to a contract between the electricity licensee and consumer; (11 in relation to cable detection work licences - the class or classes of the licences, the form and duration of such licences, the terms and conditions upon and the circumstances in which such licences may be granted, held, suspended, cancelled, altered, extended, renewed or replaced and the fees payable in respect thereof; the qualifications and other requirements to be satisfied by applicants for such licences, the examination or testing of such applicants, the fees payable in respect of such examination or testing and the circumstances in and conditions on which such applicants may be exempted from such examination or testing; and [iii) the duties and responsibilities of licensed cable detection elation to electrical or supply installations - the intervals, times and manner at or in which any electrical or supply installation shall be inspected, the notice [if any) to be given in relation to inspections and the preparations to be made by the licensees of such installations and the management for such inspections; [ii] the control of standards for electrical machinery, electric lines, wiring, fittings, accessories, appliances, consuming devices, control and protective gears associated with the generation, transmission, distribution and application of energy and the manner in which such machines, lines, wiring, fittings and apparatus shall be erected, fixed, protected, inspected, tested and maintained;\n\n(iii) the approval and control of electrical apparatuses, appliances, equipment and materials with the object of securing their safety in service and the prohibition of the use, sale or hire of all electrical apparatuses, appliances, equipment and materials which are in the opinion of the Authority unsafe; the fees to be paid for electrical or supply installation licences and any other fees which are required to be prescribed; the forms and contents of, and the conditions to be prescribed in electrical or supply installation licences and the conditions for suspension, extension and revocation of such licences and the manner in which applications for such licences shall be made; and 8th. JUNE, 2017 (vi] the means to be adopted, whether by prohibition or otherwise, to prevent or abate any nuisance or pollution likely to arise or arising from the working of any electrical or supply installation or apparatus; (nJ in relation to electrical worker licences - (iJ the class or classes of the licences, the form and duration of such licences, the terms and conditions upon and the circumstances in which such licences may be granted, held, suspended, cancelled, altered, extended, renewed or replaced and the fees payable in respect thereof; (ii] the qualifications and other requirements to be satisfied by applicants for such licences, the examination or testing of such applicants, the fees payable in respect of such examination or testing and the circumstances in and conditions on which such applicants may be exempted from such examination or testing; and\n\n(iii) the register to be kept of all electrical worker licences issued under this Order, the particulars to be entered in the register and the publication of the names of licensees; (01 the protection of the public from dangers arising from the generation, transmission or supply of electricity, from the use of electricity supplied from the installation, maintenance or use of any electric line or electrical plant; and the elimination or reduction of risks of personal injury, or damage to property or interference with its use arising therefrom; (pJ the prohibition of the supply or transmission of electricity except by means of a system approved by the Authority; (qJ the prescribing of the form of notice to be given to the Authority of accidents and of failures of the supply or transmission of electricity; and (rJ the prescribing of fees and charges and their method of payment for the purposes of this Order. (31 The Authority may in making any regulations provide that any person who contravenes the regulations is guilty of an offence and liable on conviction to a fine not exceeding $10,000, imprisonment for a term not exceeding 12 months or both and, in the case of a continuing offence, to a further fine not exceeding $250 for every day or part thereof during which the offence continues after"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"PART 7"},"heading":{"en":"Repeal"},"text":{"en":"The Electricity Act (Chapter 71) is repealed Transitional provision"}},{"id":"BN-S-51-2017-E-ELECTRICITY-ORDER-2017-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"PART 7"},"heading":{"en":"8th. TUNE. 2017"},"text":{"en":"All acts done by the Department of Electrical Sewices under the repealed Act immediately before the date of commencement of this Order shall continue to remain valid and applicable as though done by the Authority under this Order, until such time as invalidated, revoked, cancelled or otherwise determined by the Made this 13th. day of Ramadhan, 1438 Hijriah corresponding to the 8th. day of June, 2017 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM"}}],"pack":"bn-p30","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"ELECTRICITY ORDER 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-52-2015-CONSUMER-PROTECTION-FAIR-TRADING-AMENDMENT-C91F8D"] = {"id":"BN-S-52-2015-CONSUMER-PROTECTION-FAIR-TRADING-AMENDMENT-C91F8D","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"消费者保护公平交易（修正）命令 2015","en":"CONSUMER PROTECTION FAIR TRADING AMENDMENT ORDER 2015","orig":"CONSUMER PROTECTION FAIR TRADING AMENDMENT ORDER 2015","vi":"Sắc lệnh sửa đổi Sắc lệnh Bảo vệ người tiêu dùng và thương mại công bằng năm 2015","th":"คำสั่งแก้ไขเพิ่มเติมคำสั่งการคุ้มครองผู้บริโภคและการค้าที่เป็นธรรม พ.ศ. 2558","id":"Perintah Perubahan Perintah Perlindungan Konsumen dan Perdagangan yang Adil Tahun 2015","ms":"Perintah Pindaan Perintah Perlindungan Pengguna dan Perdagangan Adil 2015"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《S-52-2015-CONSUMER-PROTECTION-FAIR-TRADING-AMENDMENT-ORDER-2015.pdf》（2 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-52-2015-CONSUMER-PROTECTION-FAIR-TRADING-AMENDMENT-ORDER-2015.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-52-2015-CONSUMER-PROTECTION-FAIR-TRADING-AMENDMENT-C91F8D-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Citation and commencement"},"text":{"en":"This Order may be cited as the Consumer Protection (Fair Trading) (Amendment) Order, 2015 and shall commence on the same date as the Consumer Protection (Fair Trading) Order, 20 1 1. Amendment of First Schedule of S 641201 1"}},{"id":"BN-S-52-2015-CONSUMER-PROTECTION-FAIR-TRADING-AMENDMENT-C91F8D-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"BRUNEI DARUSSALAM GOVERNMENT GAZETTE"},"text":{"en":"The First Schedule to the Consumer Protection (Fair Trading] Order, 2011, is\n\n(a) in paragraph 1 -\n\n(i) by deleting \"1\" before \"The\" from the first line; and\n\n(ii) in subparagraph (c), by deleting \"specified in paragraph 2\".\n\n(b) by deleting paragraph 2. Made this 26th. day of Zulhijjah, 1436 Hijriah corresponding to the 10th. day of October, 2015 at Our Istana Nurul Iman, Bandar Seri Begawan, Brunei Darussalam.\n\nTHE SULTAN AND YANG DI-PERTUAN\n\nBRUNEI DARUSSALAM Dicetak oleh AWANG HAJI KAMARUL AZAM BIN HAJI MOHAMAD Pengarah Percetakan, di Jabatan Percetakan Kerajaan, Bandar Seri Begawan BB3510, Negara Brunei Darussalani."}}],"pack":"bn-p30","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"CONSUMER PROTECTION FAIR TRADING AMENDMENT ORDER 2015","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
